import docx

def dump_docx(path):
    print(f'=== {path} ===')
    doc = docx.Document(path)
    for i, p in enumerate(doc.paragraphs):
        if p.text.strip():
            print(f'P{i}: {p.text}')
    for t_idx, table in enumerate(doc.tables):
        print(f'--- Table {t_idx} ---')
        for r_idx, row in enumerate(table.rows):
            print(f'R{r_idx}: {[c.text.strip() for c in row.cells]}')

dump_docx('Projects/CFDME-2025-041_Ocotillo_WUI/Reports/CFDME-2025-041_Phase1_report_revB.docx')
dump_docx('Firm/QA/Reviews/CFDME-2025-041_peer_review_checklist.docx')
