import zipfile, xml.etree.ElementTree as ET

for fc in ['Projects/CFDME-2025-041_Ocotillo_WUI/Geometry/OAS-WUI-01_revC.FCStd', 'Projects/CFDME-2025-041_Ocotillo_WUI/Geometry/OAS-WUI-01_revD.FCStd']:
    print(f'=== {fc} ===')
    with zipfile.ZipFile(fc, 'r') as z:
        tree = ET.fromstring(z.read('Document.xml'))
        for prop in tree.iter('Property'):
            name = prop.get('name')
            val = None
            for child in prop:
                if 'value' in child.attrib:
                    val = child.attrib['value']
                elif child.text:
                    val = child.text.strip()
            print(f'  {name}: {val}')
